/* Local melody-stage inference. Bundled vendor files are unmodified. */
importScripts('./vendor/magenta/tf.min.js','./vendor/magenta/tf-backend-wasm.min.js');
const tensorflow=self.tf;let takeSeed=1,draw=0;
if(!tensorflow.env().platform)tensorflow.env().setPlatform('studio-worker',{fetch:(...args)=>self.fetch(...args),now:()=>performance.now(),encode:text=>new TextEncoder().encode(text),decode:bytes=>new TextDecoder().decode(bytes)});
// MusicRNN has no public seed argument. Sample its logits with a seeded
// categorical draw; the legacy WASM backend has no Multinomial kernel.
function sample(logits,count){const values=logits.dataSync(),max=Math.max(...values),weights=Array.from(values,v=>Math.exp(v-max)),sum=weights.reduce((a,b)=>a+b,0),picks=[];for(let i=0;i<count;i++){let t=(takeSeed+Math.imul(++draw,0x6d2b79f5))>>>0;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);let target=((t^t>>>14)>>>0)/4294967296*sum,index=weights.length-1;for(let j=0;j<weights.length;j++){target-=weights[j];if(target<=0){index=j;break;}}picks.push(index);}return tensorflow.tensor1d(picks,'int32');}
self.tf=Object.assign({},tensorflow,{multinomial:sample});
// The bundled browser compatibility module expects a window alias in workers.
self.window=self;
importScripts('./vendor/magenta/music_rnn.js');
self.onmessage=async event=>{let model;try{tensorflow.env().set('WASM_HAS_MULTITHREAD_SUPPORT',false);tensorflow.wasm.setWasmPaths(new URL('./vendor/magenta/',self.location.href).href);let backend='cpu';try{if(await tensorflow.setBackend('wasm'))backend='wasm';}catch{}if(backend==='cpu')await tensorflow.setBackend('cpu');await tensorflow.ready();self.postMessage({type:'progress',message:backend==='wasm'?'Melody model ready · accelerated':'Melody model ready · compatibility mode (slower)'});model=new self.music_rnn.MusicRNN(new URL('./vendor/magenta/chord_pitches_improv',self.location.href).href);await model.initialize();const jobs=event.data.jobs;if(!Array.isArray(jobs)||!jobs.length||jobs.length>4)throw Error('Invalid melody request.');const results=[];for(let i=0;i<jobs.length;i++){const job=jobs[i];takeSeed=job.seed>>>0;draw=0;self.postMessage({type:'progress',message:`Writing ${job.section==='bridge'?'bridge':'main theme'} · phrase ${i+1} of ${jobs.length}…`});results.push(await model.continueSequence(job.primer,job.steps,job.temperature,job.chords));await new Promise(resolve=>setTimeout(resolve,0));}self.postMessage({type:'result',results});}catch(error){self.postMessage({type:'error',message:'Melody stage: '+(error?.message||String(error))});}finally{model?.dispose();}};
